package mrpapermoon.whisper.mesh.dbimport androidx.room.Entityimport androidx.room.PrimaryKeyimport kotlinx.serialization.InternalSerializationApiimport kotlinx.serialization.Serializable@InternalSerializationApi @Serializable@Entity(tableName = WhispererEntity.TABLE_NAME)data class WhispererEntity(	@PrimaryKey	val whispererId: String,	val name: String,	val decryptionKeys: Set<ByteArray>,	val karma: Int = 0,) {	companion object {		internal const val TABLE_NAME = "known_whisperers"	}}